shell_commands:
python3 - <<'EOF'
p='src/orchestration/tools/registry.test.ts'
s=open(p).read()
assert s.rstrip().endswith('});')
idx=s.rstrip().rfind('});')
new='''
  it('compiles a function-valued inputSchema once while the returned schema object is unchanged', async () => {
    const registry = new ToolRegistry();
    const schema = {type: 'object', properties: {}};
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    registry.register({name: 'dynamic_ping', description: 'Takes no input', inputSchema: schema}, async () => 'pong');
    registry.register(() => ({name: 'lazy_ping', description: 'Takes no input', inputSchema: schema}), async () => 'pong');

    for (let call = 0; call < 10; call += 1) {
      await registry.execute('lazy_ping', {});
    }

    const {calls: compileCalls} = compile.mock;
    const count = compileCalls.length;
    compile.mockRestore();
    expect(count).toBe(1);
  });
'''
s=s[:idx]+new.lstrip('\n')+s[idx:]
open(p,'w').write(s)
EOF
timeout 300 node --experimental-vm-modules node_modules/jest/bin/jest.js src/orchestration/tools/registry.test.ts 2>&1 | tail -40
